import{_ as e,o as a,c as r,a6 as o}from"./chunks/framework.BlDtR6jM.js";const g=JSON.parse('{"title":"文学的世界（创意写作书系）","description":"","frontmatter":{"layout":"doc","title":"文学的世界（创意写作书系）","readingTime":"4 min read"},"headers":[],"relativePath":"电影和阅读/微信读书/文学_文学鉴赏/文学的世界创意写作书系.md","filePath":"电影和阅读/微信读书/文学_文学鉴赏/文学的世界创意写作书系.md"}'),l={name:"电影和阅读/微信读书/文学_文学鉴赏/文学的世界创意写作书系.md"};function n(s,t,i,_,c,d){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="文学的世界-创意写作书系" tabindex="-1">文学的世界（创意写作书系） <a class="header-anchor" href="#文学的世界-创意写作书系" aria-label="Permalink to &quot;文学的世界（创意写作书系）&quot;">​</a></h1><p><img src="https://cdn.weread.qq.com/weread/cover/22/cpplatform_xag8judarlukealxf5mfhm/t6_cpplatform_xag8judarlukealxf5mfhm1673342608.jpg" alt=" 文学的世界（创意写作书系）"></p><ul><li><strong>书名</strong>： 文学的世界（创意写作书系）</li><li><strong>作者</strong>： 刁克利</li><li><strong>简介</strong>： 名著是一种标尺，标出了文学的高度。名著是一种传承，维系着文学的命脉。阅读和欣赏名著，就是寻找一种进入文学世界的路径，寻找一种标示文学作品的尺度。进入文学的世界，挖掘大师们的写作密码，让阅读有迹可循，让创作源远流长。本书用作家的视角，通过情节、人物、主题、视角、风格、象征、背景等维度，带我们走进二十余部世界文学经典，包括《汤姆?索亚历险记》《一位女士的画像》《简?爱》《红字》《儿子与情人》《哈姆莱特》《呼啸山庄》《老人与海》《白鲸》《纪念爱米丽的一朵玫瑰花》等，让我们像作家一样阅读。换个角度读经典，寻找我们心目中的文学，让我们与文学结缘。</li><li><strong>出版时间</strong>： 2022-12-01 00:00:00</li><li><strong>ISBN</strong>： 9787300311760</li><li><strong>分类</strong>： 文学-文学鉴赏</li><li><strong>出版社</strong>： 中国人民大学出版社有限公司</li><li><strong>PC地址</strong>： <a href="https://weread.qq.com/web/reader/a8232070813ab7838g0174b0" target="_blank" rel="noreferrer">https://weread.qq.com/web/reader/a8232070813ab7838g0174b0</a></li></ul><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><blockquote><p>📌 本书强调文学的诗性。文学必须借助语言作为媒介进行创作。所谓诗性，就是文学作品附丽于同时又超越语言层面的华美品质。 ⏱ 2026-02-21 12:28:42</p></blockquote><blockquote><p>📌 除却自己的见闻，他们愿意相信别人的见闻；除却自己的经验，他们愿意相信别人的经验，以及对这种种见闻和经验的描述。所谓诗性，就是对这种超越自己的见闻和经验的信任和领悟。 ⏱ 2026-02-21 12:29:13</p></blockquote><blockquote><p>📌 它可以使我们的人生更加超凡入圣，让我们能够品味现实生活的意味深长。把它化入我们的阅读和写作，则能帮助我们洞悉文学的秘密，领略作家和思想家心之所系、情之所至。诗性就是文学的特性，诗性彰显文学独特的美与魅。寻找诗性，是一种贴近我内心的表达。笔者也借此提倡大家寻找自己心目中的文学，诗性就是笔者心目中文学的尺度。 ⏱ 2026-02-21 12:29:36</p></blockquote>',7)])])}const m=e(l,[["render",n]]);export{g as __pageData,m as default};
